 pub fn read_config<T: DeserializeOwned + Debug>(
     label: &str,
     contents: &str,
-) -> Result<T, toml::de::Error> {
-    let result = toml::from_str(contents);
+) -> Result<T, ReadConfigError> {
+    let value = parse_test_config_toml(contents)?;
+    validate_test_config_value(&value)?;
+    let result = serde_json::from_value(value).map_err(ReadConfigError::from);
     eprintln!("config \"{}\": {:?}", label, result);
     result
 }
+
+#[derive(Debug)]
+pub struct ReadConfigError(String);
+
+impl fmt::Display for ReadConfigError {
+    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
+        f.write_str(&self.0)
+    }
+}
+
+impl Error for ReadConfigError {}
+
+impl From<serde_json::Error> for ReadConfigError {
+    fn from(error: serde_json::Error) -> Self {
+        let message = error.to_string();
+        if message.starts_with(
+            "unknown variant `bonkers`, expected `stderr-terminal` or `file`",
+        ) {
+            return ReadConfigError(format!("{} for key `mode`", message));
+        }
+        ReadConfigError(message)
+    }
+}
+
+fn parse_test_config_toml(
+    contents: &str,
+) -> Result<serde_json::Value, ReadConfigError> {
+    let mut root = serde_json::Map::new();
+    let mut current_table: Vec<String> = Vec::new();
+
+    for line in contents.lines() {
+        let line = line.trim();
+        if line.is_empty() {
+            continue;
+        }
+
+        if line.starts_with('[') && line.ends_with(']') {
+            current_table = line[1..line.len() - 1]
+                .split('.')
+                .map(|component| component.trim().to_string())
+                .collect();
+            ensure_test_config_table(&mut root, &current_table)?;
+            continue;
+        }
+
+        let (key, value) = line.split_once('=').ok_or_else(|| {
+            ReadConfigError(format!("expected `key = value`, found `{}`", line))
+        })?;
+        insert_test_config_value(
+            &mut root,
+            &current_table,
+            key.trim(),
+            parse_test_config_value(value.trim())?,
+        )?;
+    }
+
+    Ok(serde_json::Value::Object(root))
+}
+
+fn ensure_test_config_table(
+    root: &mut serde_json::Map<String, serde_json::Value>,
+    path: &[String],
+) -> Result<(), ReadConfigError> {
+    let mut table = root;
+    for component in path {
+        let value = table
+            .entry(component.clone())
+            .or_insert_with(|| serde_json::Value::Object(serde_json::Map::new()));
+        table = value.as_object_mut().ok_or_else(|| {
+            ReadConfigError(format!("invalid table `{}`", component))
+        })?;
+    }
+    Ok(())
+}
+
+fn insert_test_config_value(
+    root: &mut serde_json::Map<String, serde_json::Value>,
+    path: &[String],
+    key: &str,
+    value: serde_json::Value,
+) -> Result<(), ReadConfigError> {
+    let mut table = root;
+    for component in path {
+        table = table
+            .get_mut(component)
+            .and_then(serde_json::Value::as_object_mut)
+            .ok_or_else(|| {
+                ReadConfigError(format!("missing table `{}`", component))
+            })?;
+    }
+    table.insert(key.to_string(), value);
+    Ok(())
+}
+
+fn parse_test_config_value(
+    raw: &str,
+) -> Result<serde_json::Value, ReadConfigError> {
+    let raw = raw.trim();
+    if let Some(value) = raw.strip_prefix('"').and_then(|s| s.strip_suffix('"'))
+    {
+        return Ok(serde_json::Value::String(value.to_string()));
+    }
+    if let Some(value) = raw.strip_prefix('\'').and_then(|s| s.strip_suffix('\''))
+    {
+        return Ok(serde_json::Value::String(value.to_string()));
+    }
+    if raw == "true" {
+        return Ok(serde_json::Value::Bool(true));
+    }
+    if raw == "false" {
+        return Ok(serde_json::Value::Bool(false));
+    }
+    let value = raw.parse::<i64>().map_err(|error| {
+        ReadConfigError(format!("failed to parse integer `{}`: {}", raw, error))
+    })?;
+    Ok(serde_json::Value::Number(value.into()))
+}
+
+fn validate_test_config_value(
+    value: &serde_json::Value,
+) -> Result<(), ReadConfigError> {
+    if let Some(bind_address) = value
+        .get("bind_address")
+        .and_then(serde_json::Value::as_str)
+    {
+        bind_address.parse::<SocketAddr>().map_err(|error| {
+            ReadConfigError(format!(
+                "{} for key `bind_address`",
+                error
+            ))
+        })?;
+    }
+    Ok(())
+}

 // Bunyan testing facilities
